        if not line.strip():continue
        key,explanation,anchor,*contexts=line.split('|')
        ctx=contexts[0].split(',') if contexts else []
        item=move_35.get(key,(35,''))[0]
        meta={'basis':'passage_context' if ctx else 'quran_text',**reward_meta.get(key,{})}
        keep(70,item,key,explanation=explanation,anchor=anchor,context=ctx,**meta)

